contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 cash, uint256 tenor) public {
        require(true);

        bool revertedZero;
        try c.getSwapFee(cash, 0) returns (uint256) {
            revertedZero = false;
        } catch {
            revertedZero = true;
        }

        uint256 fee = 0;
        bool revertedPos;
        if (tenor > 0) {
            try c.getSwapFee(cash, tenor) returns (uint256 f) {
                revertedPos = false;
                fee = f;
            } catch {
                revertedPos = true;
            }
        } else {
            revertedPos = false;
        }

        if (tenor > 0) {
            assert(revertedZero && !revertedPos && fee == 0);
        } else {
            assert(revertedZero);
        }
    }
}

