contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 cash, uint256 tenor) public payable {
        require(cash > 0, "cash positive");
        InitializeFeeConfigParams memory f = c.feeConfig();
        InitializeRiskConfigParams memory r = c.riskConfig();
        require(tenor >= r.minTenor && tenor <= r.maxTenor, "tenor valid");
        require(f.swapFeeAPR != 0, "swap fee apr nonzero");
        // expected: feePercent = mulDivUp(swapFeeAPR, tenor, YEAR); fee = mulDivUp(cash, feePercent, PERCENT)
        uint256 feePercent = (f.swapFeeAPR * tenor + YEAR - 1) / YEAR;
        require(feePercent <= PERCENT, "fee percent in range");
        uint256 expected = (cash * feePercent + PERCENT - 1) / PERCENT;
        uint256 fee = c.getSwapFee(cash, tenor);
        assert(fee == expected);
    }
    receive() external payable {}
}

