contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 cash, uint256 tenor, uint256 aprBound) public {
        // bound inputs so that swapFeeAPR * tenor cannot overflow uint256
        require(cash > 0 && cash <= 1e30, "cash bound");
        require(tenor > 0 && tenor <= 1e18, "tenor bound");
        require(aprBound <= 1e18, "apr bound");

        // set the swap fee APR through the admin surface if possible; we only need the
        // currently configured swapFeeAPR and tenor to predict the fee
        InitializeFeeConfigParams memory f = c.feeConfig();
        uint256 swapFeeAPR = f.swapFeeAPR;
        uint256 expectedFeePercent = FixedPointMathLib.mulDivUp(swapFeeAPR, tenor, YEAR);
        uint256 expectedFee = FixedPointMathLib.mulDivUp(cash, expectedFeePercent, PERCENT);

        uint256 actual = c.getSwapFee(cash, tenor);

        assert(actual == expectedFee);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 cash, uint256 tenor) public {
        // bound inputs so that swapFeeAPR * tenor cannot overflow uint256
        require(cash > 0 && cash <= 1e24, "cash bound");
        require(tenor > 0 && tenor <= 1e12, "tenor bound");

        InitializeFeeConfigParams memory f = c.feeConfig();
        uint256 apr = f.swapFeeAPR;
        require(apr <= 1e18, "apr bound"); // apr * tenor <= 1e30, safe in uint256

        // expected fee percent = ceil(apr * tenor / YEAR)
        uint256 feePercent = (apr * tenor + YEAR - 1) / YEAR;
        // expected fee = ceil(cash * feePercent / PERCENT)
        uint256 expected = (cash * feePercent + PERCENT - 1) / PERCENT;

        uint256 actual = c.getSwapFee(cash, tenor);

        assert(actual == expected);
    }
}

